export interface StoryTestResult {
  /** The id of the story that was tested. */
  storyId: string;

  /** The normalized status of the test run. */
  status: 'PASS' | 'FAIL' | 'PENDING';

  /** The extracted, human-readable error message (first line), if the test failed. */
  error?: string;

  /** The full stack trace associated with the error, if any. */
  stack?: string;

  /**
   * Whether the story passed but rendered nothing visible. Only ever set to `true` for passing
   * stories.
   */
  emptyRender?: boolean;
}

/** Aggregated information about a single error category across a test run. */
export interface CategorizedError {
  /** How many failures fell into this category. */
  count: number;

  /** How many unique error messages fell into this category. */
  uniqueCount: number;

  /** Whitelisted dependencies detected in the stack traces for this category. */
  matchedDependencies: string[];
}

/** A summary of an entire test run, with failures grouped into error categories. */
export interface TestRunAnalysis {
  /** Total number of tests in the run. */
  total: number;

  /** Number of tests that passed. */
  passed: number;

  /** Number of tests that passed but rendered nothing visible. */
  passedButEmptyRender: number;

  /** Ratio of passing tests to total tests, rounded to two decimals. */
  successRate: number;

  /** Ratio of meaningfully passing tests (excluding empty renders) to total tests. */
  successRateWithoutEmptyRender: number;

  /** Number of unique error messages across all failures. */
  uniqueErrorCount: number;

  /** Failures grouped by error category. */
  categorizedErrors: Record<string, CategorizedError>;
}
