/** ANSI escape sequences (e.g. color codes) that may be embedded in error output. */
const ANSI_ESCAPE_PATTERN = /\[[0-9;]*m/g;

/**
 * Storybook's component test addon prepends a "Click to debug" banner to error messages (see
 * addon-vitest's `setup-file.ts`). We strip it so the underlying error message can be extracted
 * and categorized consistently.
 */
const DEBUG_BANNER_PATTERN = /Click to debug the error directly in Storybook:.*$/gm;

/** Remove ANSI escape codes and Storybook debug banners from a piece of error text. */
function stripDebugBanner(text: string): string {
  return text.replace(ANSI_ESCAPE_PATTERN, '').replace(DEBUG_BANNER_PATTERN, '');
}

