/** Round a ratio to two decimals (returns a number, e.g. `0.33`). */
function toRate(numerator: number, denominator: number): number {
  return denominator > 0 ? parseFloat((numerator / denominator).toFixed(2)) : 0;
}

/**
 * Categorize the failures within a set of test results.
 *
 * Only `FAIL` results with a non-empty error string are considered. Returns the total number of
 * failures, the number of unique error messages, and the failures grouped by category.
 */
export function extractCategorizedErrors(testResults: StoryTestResult[]): {
  totalErrors: number;
  uniqueErrorCount: number;
  categorizedErrors: Record<string, CategorizedError>;
} {
  const failed = testResults.filter((r) => r.status === 'FAIL' && r.error);

  // Map: category -> { count, uniqueErrors: Set<string>, matchedDependencies }
  const map = new Map<
    ErrorCategory,
    { count: number; uniqueErrors: Set<string>; matchedDependencies: Set<string> }
  >();

  // To count unique error messages (by their message, not by category)
  const uniqueErrorMessages = new Set<string>();

  for (const r of failed) {
    const { category, matchedDependencies } = categorizeError(r.error!, r.stack);

    if (!map.has(category)) {
      map.set(category, { count: 0, uniqueErrors: new Set(), matchedDependencies: new Set() });
    }

    const data = map.get(category)!;
    data.count++;
    matchedDependencies.forEach((dep) => data.matchedDependencies.add(dep));

    // Use the full error message for unique error message counting
    uniqueErrorMessages.add(r.error!);
    data.uniqueErrors.add(r.error!);
  }

  const categorizedErrors = Array.from(map.entries()).reduce<Record<string, CategorizedError>>(
    (acc, [category, data]) => {
      acc[category] = {
        count: data.count,
        uniqueCount: data.uniqueErrors.size,
        matchedDependencies: Array.from(data.matchedDependencies).sort(),
      };
      return acc;
    },
    {}
  );

  return {
    totalErrors: failed.length,
    uniqueErrorCount: uniqueErrorMessages.size,
    categorizedErrors,
  };
}

/**
 * Analyze a set of normalized story test results and return an aggregated summary.
 *
 * Computes pass/fail totals, success rates (with and without empty renders), the number of unique
 * error messages, and the failures grouped by error category.
 */
export function analyzeTestResults(results: StoryTestResult[]): TestRunAnalysis {
  const total = results.length;
  const passed = results.filter((r) => r.status === 'PASS').length;
  const passedButEmptyRender = results.filter((r) => r.status === 'PASS' && r.emptyRender).length;

  const successRate = toRate(passed, total);
  const successRateWithoutEmptyRender = toRate(passed - passedButEmptyRender, total);

  const { uniqueErrorCount, categorizedErrors } = extractCategorizedErrors(results);

  return {
    total,
    passed,
    passedButEmptyRender,
    successRate,
    successRateWithoutEmptyRender,
    uniqueErrorCount,
    categorizedErrors,
  };
}
